mapper.update:
UPDATE task_review
SET score   = #{score},
    `comment` = #{comment}
WHERE id = #{id}

mapper.select:
SELECT 
FROM task_review r
WHERE r.id = #{id}

SELECT 
FROM task_review r


        AND r.submission_id = #{submissionId}


        AND r.reviewer_id = #{reviewerId}

SELECT 
FROM task_review r
         JOIN task_submission s ON s.id = r.submission_id

    AND s.user_id = #{userId}

        AND r.submission_id = #{submissionId}

SELECT 
FROM task_review r

    AND r.reviewer_id = #{userId}

        AND r.submission_id = #{submissionId}


        AND r.reviewer_id = #{reviewerId}
